import { sql } from "drizzle-orm";
import { db } from "@reading-advantage/db";
import { auditEvents, users, schools } from "@reading-advantage/db/schema";
import { exportSubjectData, DSAR_ROW_CEILING } from "../audit/dsar.js";

/**
