    pool: "forks",
    poolOptions: { forks: { singleFork: true } },
  },
  resolve: {
    alias: {
      "@": resolve(__dirname, "./"),
      "server-only": resolve(__dirname, "./lib/test/server-only-mock.ts"),
    },
  },
